@dataclass

def _parse_nmap_stdout(stdout: str, tool_name: str) -> list[dict[str, Any]]:
    entities: list[dict[str, Any]] = []
    current_host: dict[str, Any] | None = None
    for line in stdout.splitlines():
        stripped = line.strip()
        if not stripped:
            continue
        if stripped.startswith("Nmap scan report for"):
            host_val = stripped.replace("Nmap scan report for ", "").strip()
            current_host = {"host": host_val, "type": "domain", "source": tool_name}
            entities.append(current_host)
        elif stripped.startswith("Host is up"):
            if current_host is not None:
                current_host["status"] = "up"
        elif "open" in stripped and "/" in stripped:
            port_info = {
                "port_line": stripped,
                "source": tool_name,
            }
            entities.append(port_info)
    return entities

def _parse_nikto_stdout(stdout: str, tool_name: str) -> list[dict[str, Any]]:
    entities: list[dict[str, Any]] = []
    for line in stdout.splitlines():
        stripped = line.strip()
        if not stripped or stripped.startswith("+") or stripped.startswith("-"):
            continue
        if "+" in stripped:
            parts = stripped.split("+")
            if len(parts) >= 2:
                entities.append(
                    {
                        "finding": parts[1].strip(),
                        "type": "web_finding",
                        "source": tool_name,
                    }
                )
    return entities

def _parse_sqlmap_stdout(stdout: str, tool_name: str) -> list[dict[str, Any]]:
    entities: list[dict[str, Any]] = []
    for line in stdout.splitlines():
        stripped = line.strip()
        if not stripped:
            continue
        if "parameter" in stripped.lower() and "injectable" in stripped.lower():
            entities.append(
                {
                    "finding": stripped,
                    "type": "sqli_finding",
                    "source": tool_name,
                }
            )
        elif "sqlmap" in stripped.lower() and any(
            kw in stripped.lower() for kw in ["GET", "POST", "Cookie", "Referer"]
        ):
            entities.append(
                {
                    "finding": stripped,
                    "type": "sqli_parameter",
                    "source": tool_name,
                }
            )
    return entities

def _parse_dnsrecon_stdout(stdout: str, tool_name: str) -> list[dict[str, Any]]:
    entities: list[dict[str, Any]] = []
    for line in stdout.splitlines():
        stripped = line.strip()
        if not stripped:
            continue
        if "[" in stripped and "]" in stripped:
            entities.append(
                {
                    "record": stripped,
                    "type": "dns_record",
                    "source": tool_name,
                }
            )
    return entities

def _parse_harvester_stdout(stdout: str, tool_name: str) -> list[dict[str, Any]]:
    entities: list[dict[str, Any]] = []
    for line in stdout.splitlines():
        stripped = line.strip()
        if not stripped:
            continue
        if "@" in stripped and "." in stripped.split("@")[-1]:
            entities.append(
                {
                    "email": stripped,
                    "type": "email",
                    "source": tool_name,
                }
            )
        elif stripped.startswith("http") or stripped.startswith("www"):
            entities.append(
                {
                    "url": stripped,
                    "type": "url",
                    "source": tool_name,
                }
            )
    return entities

def _send_slack(webhook_url: str, title: str, body: str, severity: str) -> bool:
    """Send a Slack message via Incoming Webhook."""
    color_map = {"info": "#5B8FF9", "warning": "#F6BD16", "error": "#FF6B6B"}
    payload = {
        "attachments": [{
            "color": color_map.get(severity, "#5B8FF9"),
            "title": title,
            "text": body[:2000],
            "footer": "Estorides Monitor",
            "ts": int(time.time()),
        }],
    }
    return _http_post(webhook_url, payload)

def _send_discord(webhook_url: str, title: str, body: str, severity: str) -> bool:
    """Send a Discord embed via Webhook."""
    color_map = {"info": 6003455, "warning": 16167446, "error": 16711680}
    payload = {
        "embeds": [{
            "title": title[:256],
            "description": body[:2000],
            "color": color_map.get(severity, 6003455),
            "footer": {"text": "Estorides Monitor"},
            "timestamp": datetime.utcnow().isoformat() + "Z",
        }],
    }
    return _http_post(webhook_url, payload)

def _send_telegram(
    bot_token: str, chat_id: str, title: str, body: str, severity: str,
) -> bool:
    """Send a Telegram message via Bot API."""
    text = f"*{title}*\n\n{body[:3000]}"
    url = f"https://api.telegram.org/bot{bot_token}/sendMessage"
    payload = {
        "chat_id": chat_id,
        "text": text,
        "parse_mode": "Markdown",
        "disable_web_page_preview": True,
    }
    return _http_post(url, payload)

def _send_webhook(
    webhook_url: str, title: str, body: str, severity: str,
) -> bool:
    """Send a generic webhook POST."""
    payload = {
        "event": "estorides_alert",
        "severity": severity,
        "title": title,
        "body": body[:5000],
        "timestamp": time.time(),
    }
    return _http_post(webhook_url, payload)


