    rate_limited: bool = False,
) -> CodeExposureResult:
    summary = SeveritySummary()
    for f in findings:
        sev = f.severity.lower()
        if sev == "critical":
            summary.critical += 1
        elif sev == "high":
            summary.high += 1
        elif sev == "medium":
            summary.medium += 1
        elif sev == "low":
            summary.low += 1
        else:
            summary.info += 1

    return CodeExposureResult(
        findings=findings,
        total_findings=len(findings),
        severity_summary=summary,
        rate_limited=rate_limited,
