def _scan_keywords(text: str) -> List[Tuple[str, str]]:
    """Scan a text blob for ATT&CK-relevant keywords."""
    if not text:
        return []
    lower = text.lower()
    out: List[Tuple[str, str]] = []
    seen: set[str] = set()
    for needle, tid, label in _KEYWORD_PATTERNS:
        if needle in lower and tid not in seen:
            seen.add(tid)
            out.append((tid, label))
    return out

def map_observation(observation: Dict[str, Any]) -> Dict[str, Any]:
    """Return ATT&CK techniques associated with an observation.

    Output:
        {
          "techniques": [
            {"id": "T1595", "label": "Active Scanning", "via": "source:shodan_internetdb"},
            ...
          ],
          "tactic_ids": ["TA0043"],  # not populated yet — future
        }
    """
    src = observation.get("source", "")
    techniques: List[Dict[str, str]] = []
    seen: set[str] = set()

    for tid, label in _TECHNIQUE_TABLE.get(src, []):
        if tid in seen:
            continue
        seen.add(tid)
        techniques.append({"id": tid, "label": label, "via": f"source:{src}"})

    # Keyword scan on the raw + parsed payloads.
    import json
    blob_parts: List[str] = []
    for k in ("raw", "parsed"):
        v = observation.get(k)
        if v is None:
            continue
        try:
            blob_parts.append(json.dumps(v, ensure_ascii=False, default=str)[:20000])
        except (TypeError, ValueError):
            blob_parts.append(str(v)[:20000])
    blob = "\n".join(blob_parts)
    for tid, label in _scan_keywords(blob):
        if tid in seen:
            continue
        seen.add(tid)
        techniques.append({"id": tid, "label": label, "via": "keyword"})

def map_observations(observations: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Bulk mapper. Stamps each observation in place with `_mitre` key.

    Returns the list of observations (for chaining). Mutates in place
    for performance — the orchestrator doesn't keep references to the
    pre-mapping list, so a side effect is safe.
    """
    for obs in observations:
        try:
            obs["mitre"] = map_observation(obs)
        except Exception as e:  # noqa: BLE001
            log.debug("mitre mapping failed for %s: %s", obs.get("source"), e)
            obs["mitre"] = {"techniques": [], "error": str(e)}
    return observations

def all_techniques_for(observations: List[Dict[str, Any]]) -> List[Dict[str, str]]:
    """Aggregate: unique techniques across all observations, sorted by id."""
    seen: Dict[str, Dict[str, str]] = {}
    for obs in observations:
        for t in obs.get("mitre", {}).get("techniques", []):
            tid = t["id"]
            if tid not in seen:
                seen[tid] = t
    return sorted(seen.values(), key=lambda x: x["id"])

def __post_init__(self) -> None:
    if not self.next_run_at:
        self.next_run_at = time.time() + 60  # first run in 60s

def get_watch(self, watch_id: str) -> WatchTarget | None:
    with self._lock:
        row = self._conn.execute(
            "SELECT * FROM watch_targets WHERE id=?", (watch_id,)
        ).fetchone()
    if not row:
        return None
    return WatchTarget.from_row(row)

def delete_watch(self, watch_id: str) -> None:
    with self._tx() as c:
        c.execute("DELETE FROM watch_targets WHERE id=?", (watch_id,))

def history(self, watch_id: str, limit: int = 20) -> list[dict[str, Any]]:
    with self._lock:
        rows = self._conn.execute(
            "SELECT started_at, completed_at, status, entity_count, "
            "obs_count, error, alert_sent FROM watch_history "
            "WHERE watch_id=? ORDER BY started_at DESC LIMIT ?",
            (watch_id, limit),
        ).fetchall()
    return [
        {
            "started_at": r[0], "completed_at": r[1],
            "status": r[2], "entity_count": r[3],
            "obs_count": r[4], "error": r[5], "alert_sent": bool(r[6]),
        }
        for r in rows
    ]

    def stats(self) -> dict[str, Any]:
        with self._lock:
            total = self._conn.execute(
                "SELECT count(*) FROM watch_targets"
            ).fetchone()[0]
            enabled = self._conn.execute(
                "SELECT count(*) FROM watch_targets WHERE enabled=1"
            ).fetchone()[0]
        return {"total": total, "enabled": enabled}


# ---------------------------------------------------------------------------
# WatchScheduler — threaded scheduler loop
# ---------------------------------------------------------------------------

def running(self) -> bool:
    return self._thread is not None and self._thread.is_alive()

@property

def has_runner(self) -> bool:
    """True once an executor has been wired via set_runner()."""
    return self._runner is not None

def start(self) -> None:
    if self.running:
        log.warning("scheduler already running")
        return
    self._stop.clear()
    self._thread = threading.Thread(
        target=self._loop, daemon=True, name="estorides-scheduler"
    )
    self._thread.start()
    log.info("scheduler started (poll interval=%ds)", SCHEDULER_POLL_INTERVAL_S)

def stop(self) -> None:
    self._stop.set()
    if self._thread:
        self._thread.join(timeout=5)
        log.info("scheduler stopped")

def set_runner(self, runner: Callable[[WatchTarget], dict[str, Any] | Awaitable[dict[str, Any]]]) -> None:
    """Set the orchestrator runner function (sync or async)."""
