def _domain_from_query(q: str) -> Optional[str]:
    """Heuristic: if the query looks like a domain, return it; if it's an IP, return None."""
    q = q.strip()
    if re.match(r"^\d{1,3}(\.\d{1,3}){3}$", q):
        return None
    if re.match(r"^[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)+$", q):
        return q.lower()
    return None

