            "vulnerabilityName": vd.get("vulnerabilityName", ""),
            "dateAdded": vd.get("dateAdded", ""),
            "dueDate": vd.get("dueDate", ""),
        })
    return {"vulnerabilities": out, "total": len(vulns)}

