    if not isinstance(payload, list) or not payload:
        return []
    header = payload[0]
    if not isinstance(header, list) or not all(isinstance(h, str) for h in header):
        return []
    out = []
    for row in payload[1:50]:
        if not isinstance(row, list):
            continue
        out.append(dict(zip(header, row)))
    return out

