def _normalize_value(etype: str, value: str) -> str:
    """Deterministic normalisation matching fusion_store.entity_id."""
    return f"{etype}:{(value or '').strip().lower()}"

def _canonical_id(etype: str, value: str) -> str:
    """Deterministic sha1-based entity id matching fusion_store convention."""
    return stable_id(_normalize_value(etype, value))

def _corroboration_factor(source_count: int) -> float:
    """Logarithmic corroboration weight: min(1, log10(1 + n))."""
    if source_count <= 0:
        return 0.0
    return min(1.0, math.log10(1.0 + source_count))

def _freshness_factor(age_hours: float, max_hours: float) -> float:
    """Linear freshness decay from 1.0 (fresh) to 0.1 (stale)."""
    if age_hours <= 0.0:
        return 1.0
    ratio = age_hours / max_hours
    return max(0.1, 1.0 - ratio)

def _direct_match_query(value: str, query: str) -> bool:
    """True if the entity value matches the original query."""
    return value.strip().lower() == query.strip().lower()

def _extract_key_findings(observations: list[dict[str, Any]]) -> list[str]:
    """Extract textual key findings from a list of observations."""
    findings: list[str] = []
    for obs in observations:
        parsed = obs.get("parsed")
        if not isinstance(parsed, dict):
            continue
        for key, val in parsed.items():
            if isinstance(val, str) and len(val) > 2 and len(val) < 100:
                finding = f"{key}: {val}"
                if finding not in findings:
                    findings.append(finding)
            elif isinstance(val, list) and len(val) > 0:
                for item in val[:3]:
                    if isinstance(item, str) and len(item) > 2 and len(item) < 100:
                        finding = f"{key}: {item}"
                        if finding not in findings:
                            findings.append(finding)
        if len(findings) >= 5:
            break
    return findings[:5]

def run_passive_recon(
    query: str,
    headers: dict | None = None,
    html: str | None = None,
    cookies: list[str] | None = None,
    employees: list[Employee] | None = None,
    code_findings: list | None = None,
    third_parties: list[ThirdParty] | None = None,
    pdns_subdomains: list | None = None,
    cloud_assets: list | None = None,
) -> dict:
    headers = headers or {}
    html = html or ""
    employees = employees or []
    code_findings = code_findings or []
    third_parties = third_parties or []
    pdns_subdomains = pdns_subdomains or []
    cloud_assets = cloud_assets or []

    result: dict = {}

    tech_result = fingerprint(headers, html, cookies)
    result["tech_fingerprint"] = tech_result.to_dict() if hasattr(tech_result, "to_dict") else {}

    vuln_result = correlate_technologies(
        tech_result.technologies if hasattr(tech_result, "technologies") else []
    )
    result["vuln_correlation"] = vuln_result.to_dict() if hasattr(vuln_result, "to_dict") else {}

    if employees:
        intel_result = analyse_employees(employees, query)
        result["people_intel"] = intel_result.to_dict() if hasattr(intel_result, "to_dict") else {}

    cloud_data = CloudAssetDiscoveryResult(
        assets=cloud_assets,
        total_assets=len(cloud_assets),
        accessible_count=sum(1 for a in cloud_assets if getattr(a, "accessible", False)),
        listing_count=sum(1 for a in cloud_assets if getattr(a, "listing_enabled", False)),
    )
    result["cloud_assets"] = cloud_data.to_dict() if hasattr(cloud_data, "to_dict") else {}

