@dataclass(frozen=True)

def _corroboration_weight(n: int) -> float:
    """``min(1, log10(1 + n))``.  0 sources → 0; 1 → 0.30; 9 → 1.0."""
    if n <= 0:
        return 0.0
    return min(1.0, math.log10(1.0 + n))

def _freshness_weight(age_seconds: float, half_life_days: float) -> float:
    """Exponential decay.  age=0 → 1.0; one half-life → 0.5."""
    if half_life_days <= 0.0:
        raise ValueError("half_life_days must be > 0")
    if age_seconds <= 0.0:
        return 1.0
    age_days = age_seconds / 86400.0
    return math.exp(-math.log(2) * age_days / half_life_days)

def _validate_score(value: float, field_name: str) -> None:
    if not 0.0 <= value <= 1.0:
        raise ValueError(f"{field_name} must be in [0, 1], got {value!r}")

def _clamp01(value: float) -> float:
    """Clamp to the closed unit interval."""
    if value < 0.0:
        return 0.0
    if value > 1.0:
        return 1.0
    return value


# --------------------------------------------------------------------------- public

def reliability_from_name(source_name: str | None) -> SourceReliability:
    """Look up the reliability for a source by name; never raises.

    Operator input is potentially adversarial. We do not log, do not
    validate beyond ``lower().strip()``, and never raise. Unknown names
    fall back to :data:`DEFAULT_RELIABILITY`.
    """
    if not source_name:
        return DEFAULT_RELIABILITY
    key = source_name.strip().lower()
    if not key:
        return DEFAULT_RELIABILITY
    return SOURCE_RELIABILITY_MAP.get(key, DEFAULT_RELIABILITY)

def source_type_from_name(source_name: str | None) -> SourceType:
    """Look up the source type hierarchy for a source by name; never raises.

    Operator input is potentially adversarial. Same contract as
    :func:`reliability_from_name`: no logging, no raising, no ReDoS.
    Unknown names fall back to :data:`DEFAULT_SOURCE_TYPE` (TERTIARY).
    """
    if not source_name:
        return DEFAULT_SOURCE_TYPE
    key = source_name.strip().lower()
    if not key:
        return DEFAULT_SOURCE_TYPE
    return SOURCE_TYPE_MAP.get(key, DEFAULT_SOURCE_TYPE)

def reliability_weight(
    source_name: str | None,
    overrides: Mapping[str, str] | None = None,
) -> float:
    """Numeric reliability weight for a source name; never raises.

    `overrides` maps a source name to an explicit reliability letter
    (used by the recon-fusion config). An invalid override letter falls
    back to C, matching the historical behaviour. Unknown names fall back
    to :data:`RELIABILITY_WEIGHT` for :data:`DEFAULT_RELIABILITY`.
    """
    lookup = overrides.get(source_name) if overrides and source_name else None
    if lookup is None:
        rel = reliability_from_name(source_name)
    else:
        try:
            rel = SourceReliability(str(lookup).strip().upper())
        except ValueError:
            rel = DEFAULT_RELIABILITY
    return RELIABILITY_WEIGHT.get(rel, RELIABILITY_WEIGHT[DEFAULT_RELIABILITY])

def normalise_asset(raw: str) -> str:
    """Reduce a raw asset string to a comparable host or IP literal.

    Strips an optional scheme, any path/query, a port, surrounding
    whitespace and a trailing dot, and lowercases the result. A value that
    is already a bare host or IP passes through unchanged (bar casing)."""
    asset = raw.strip().lower()
    if not asset:
        return ""
    if "://" in asset:
        asset = asset.split("://", 1)[1]
    # Drop path, query and fragment.
    for sep in ("/", "?", "#"):
        if sep in asset:
            asset = asset.split(sep, 1)[0]
    # Drop credentials.
    if "@" in asset:
        asset = asset.rsplit("@", 1)[1]
    asset = asset.strip("[]")  # bracketed IPv6
    # Drop a trailing :port, but never the colons of an IPv6 literal.
    if asset.count(":") == 1:
        host, _, port = asset.partition(":")
        if port.isdigit():
            asset = host
    return asset.rstrip(".")

def is_ip(asset: str) -> bool:
    """True when `asset` parses as a bare IPv4 or IPv6 address."""
    try:
        ipaddress.ip_address(asset)
        return True
    except ValueError:
        return False


# ------------------------------------------------------------------- rules

class ScopeRule(ABC):
    """A single scope predicate. Implementations match exactly one grammar."""

    @abstractmethod

def matches(self, asset: str) -> bool:
    """True when `asset` (already normalised) is covered by this rule."""

@abstractmethod

    def describe(self) -> str:
        """Human-readable form of the rule, for reports and audit."""


@dataclass(frozen=True)

class WildcardRule(ScopeRule):
    """`*.example.com` — the apex and any subdomain of it."""

    suffix: str  # the part after the leading '*.', e.g. "example.com"

def matches(self, asset: str) -> bool:
    if is_ip(asset):
        return False
    return asset == self.suffix or asset.endswith("." + self.suffix)

    def describe(self) -> str:
        return f"*.{self.suffix}"


@dataclass(frozen=True)

class ExactHostRule(ScopeRule):
    """A single fully-qualified host, matched verbatim."""

    host: str

    def describe(self) -> str:
        return self.host


@dataclass(frozen=True)

class CidrRule(ScopeRule):
    """An IPv4/IPv6 network; matches any address inside it."""

    network: ipaddress._BaseNetwork

def matches(self, asset: str) -> bool:
    if not is_ip(asset):
        return False
    try:
        return ipaddress.ip_address(asset) in self.network
    except ValueError:
        return False

    def describe(self) -> str:
        return str(self.network)


@dataclass(frozen=True)

class RegexRule(ScopeRule):
    """A compiled regex matched against the raw normalised asset."""

    pattern: "re.Pattern[str]"

    def describe(self) -> str:
        return f"re:{self.pattern.pattern}"


# ----------------------------------------------------------- rule factories

def _wildcard_factory(text: str) -> Optional[ScopeRule]:
    if text.startswith("*."):
        suffix = normalise_asset(text[2:])
        return WildcardRule(suffix) if suffix else None
    return None

def _regex_factory(text: str) -> Optional[ScopeRule]:
    if text.startswith("re:"):
        body = text[3:].strip()
        try:
            return RegexRule(re.compile(body, re.IGNORECASE))
        except re.error as e:
            log.warning("invalid scope regex %r: %s", body, e)
            return None
    return None

def _cidr_factory(text: str) -> Optional[ScopeRule]:
    if "/" in text:
        try:
            return CidrRule(ipaddress.ip_network(text, strict=False))
        except ValueError:
            return None
    return None

def _ip_factory(text: str) -> Optional[ScopeRule]:
    if is_ip(text):
        # A bare IP is a /32 or /128 network so one code path covers it.
        return CidrRule(ipaddress.ip_network(text, strict=False))
    return None

def parse_rule(line: str) -> Optional[ScopeRule]:
    """Parse one rule line into a ScopeRule, or None for blank/comment/invalid."""
    text = line.strip()
    if not text or text.startswith("#"):
        return None
    for factory in _RULE_FACTORIES:
        rule = factory(text)
        if rule is not None:
            return rule
    return None

def parse_rules(lines: Iterable[str]) -> List[ScopeRule]:
    """Parse many rule lines, skipping blanks, comments and invalid entries."""
    rules: List[ScopeRule] = []
    for line in lines:
        rule = parse_rule(line)
        if rule is not None:
            rules.append(rule)
    return rules


# ------------------------------------------------------------------ matcher

def __init__(
    self,
    in_scope: Sequence[ScopeRule],
    out_of_scope: Sequence[ScopeRule] = (),
) -> None:
    self._in = list(in_scope)
    self._out = list(out_of_scope)

@property

def in_rules(self) -> List[ScopeRule]:
    return list(self._in)

@property

def classify(self, raw_asset: str) -> str:
    """Return IN_SCOPE, OUT_OF_SCOPE or UNKNOWN for a single asset."""
    asset = normalise_asset(raw_asset)
    if not asset:
        return UNKNOWN
    if any(rule.matches(asset) for rule in self._out):
        return OUT_OF_SCOPE
    if any(rule.matches(asset) for rule in self._in):
        return IN_SCOPE
    return UNKNOWN

    def partition(self, assets: Iterable[str]) -> Dict[str, List[str]]:
        """Bucket many assets, returning sorted, de-duplicated lists.

        Keys are IN_SCOPE, OUT_OF_SCOPE and UNKNOWN. De-duplication is on
        the normalised form so `HTTPS://Example.com/` and `example.com`
        collapse to one entry."""
        buckets: Dict[str, set] = {IN_SCOPE: set(), OUT_OF_SCOPE: set(), UNKNOWN: set()}
        for raw in assets:
            asset = normalise_asset(raw)
            if not asset:
                continue
            buckets[self.classify(asset)].add(asset)
        return {key: sorted(values) for key, values in buckets.items()}


# ------------------------------------------------------------- file loading

def load_assets(path: Path) -> List[str]:
    """Read assets from a file: a discover surface JSON or a flat host list.

    A JSON document is mined for assets in `domains`, `entities` (values of
    host/ip types) and any top-level list of strings. Anything else is read
    as one asset per line."""
    text = path.read_text(encoding="utf-8")
    stripped = text.lstrip()
    if stripped.startswith(("{", "[")):
        try:
            return _assets_from_json(json.loads(text))
        except (json.JSONDecodeError, TypeError, ValueError):
            log.debug("asset file %s is not parseable JSON, reading as lines", path)
    return [line for line in (ln.strip() for ln in text.splitlines()) if line and not line.startswith("#")]


_HOST_ENTITY_TYPES = frozenset({"domain", "ipv4", "ipv6", "url", "host"})

def _assets_from_json(doc: object) -> List[str]:
    """Extract candidate assets from a parsed discover/result JSON document."""
    assets: List[str] = []
    if isinstance(doc, list):
        assets.extend(str(item) for item in doc if isinstance(item, (str, int)))
        return assets
    if isinstance(doc, dict):
        domains = doc.get("domains")
        if isinstance(domains, list):
            assets.extend(str(d) for d in domains)
        entities = doc.get("entities")
        if isinstance(entities, list):
            for ent in entities:
                if isinstance(ent, dict) and ent.get("type") in _HOST_ENTITY_TYPES:
                    value = ent.get("value")
                    if value:
                        assets.append(str(value))
    return assets


# ------------------------------------------------------------- flat export
@dataclass(frozen=True)

class ScopeReport:
    """Classified assets plus the flat lists an operator pipes onward."""

    in_scope: List[str]
    out_of_scope: List[str]
    unknown: List[str]

    @property

def hosts(self) -> List[str]:
    """In-scope hostnames (everything in-scope that is not an IP)."""
    return [a for a in self.in_scope if not is_ip(a)]

@property

def ips(self) -> List[str]:
    """In-scope bare IP addresses."""
    return [a for a in self.in_scope if is_ip(a)]

def to_dict(self) -> Dict[str, List[str]]:
    return {
        "in_scope": self.in_scope,
        "out_of_scope": self.out_of_scope,
        "unknown": self.unknown,
        "in_scope_hosts": self.hosts,
        "in_scope_ips": self.ips,
    }

def build_report(matcher: ScopeMatcher, assets: Iterable[str]) -> ScopeReport:
    """Classify `assets` with `matcher` and return a :class:`ScopeReport`."""
    buckets = matcher.partition(assets)
    return ScopeReport(
        in_scope=buckets[IN_SCOPE],
        out_of_scope=buckets[OUT_OF_SCOPE],
        unknown=buckets[UNKNOWN],
    )

def write_flat_lists(report: ScopeReport, out_dir: Path) -> Dict[str, Path]:
    """Write newline-delimited flat lists for piping into active tooling.

    Produces `in_scope_hosts.txt`, `in_scope_ips.txt` and `unknown.txt`
    under `out_dir`. Returns the map of label to written path."""
    out_dir.mkdir(parents=True, exist_ok=True)
    files = {
        "in_scope_hosts": report.hosts,
        "in_scope_ips": report.ips,
        "unknown": report.unknown,
    }
    written: Dict[str, Path] = {}
    for label, items in files.items():
        target = out_dir / f"{label}.txt"
        target.write_text("\n".join(items) + ("\n" if items else ""), encoding="utf-8")
        written[label] = target
    return written

def disallowed_brands_in(text: str) -> tuple[str, ...]:
    """Return the third-party brand tokens found in ``text``.

    Matching is case-insensitive and word-boundary aware so an ordinary word
    that merely contains a brand as a substring does not produce a false
    positive. The returned tuple holds the canonical lowercase brand names in
    first-seen order, de-duplicated.
    """
    seen: dict[str, None] = {}
    for match in _BRAND_RE.finditer(text):
        seen.setdefault(match.group(0).lower(), None)
    return tuple(seen)

def emoji_in(text: str) -> tuple[str, ...]:
    """Return the emoji glyphs found in ``text``, de-duplicated in order.

    Emoji are codepoints in the pictographic blocks (Miscellaneous Symbols,
    Dingbats, regional indicators, the supplementary pictographic planes) and
    the emoji variation selector. Geometric line-symbols outside those blocks
    are permitted iconography and are not flagged.
    """
    seen: dict[str, None] = {}
    for match in _EMOJI_RE.finditer(text):
        seen.setdefault(match.group(0), None)
    return tuple(seen)

def percent_encoded_emoji_in(text: str) -> tuple[str, ...]:
    """Return percent-encoded supplementary-plane emoji sequences in ``text``.

    Catches an emoji smuggled into a ``data:`` URI (for example an emoji
    favicon) as the UTF-8 lead bytes ``%F0%9F`` followed by two continuation
    bytes. The returned tuple holds the matched sequences in first-seen order.
    """
    seen: dict[str, None] = {}
    for match in _PERCENT_EMOJI_RE.finditer(text):
        seen.setdefault(match.group(0), None)
    return tuple(seen)


@dataclass(frozen=True)

class KeyboardShortcut:
    """A single keyboard shortcut: the key chord and what it does."""

    keys: str
    description: str


@dataclass(frozen=True)

class SplashTip:
    """A single onboarding tip: a short title and a one-line body."""

    title: str
    body: str


@dataclass(frozen=True)

def _assert_clean(label: str, *texts: str) -> None:
    """Raise :class:`InvalidTelemetryConfigError` if any text leaks brand/emoji."""
    for text in texts:
        if disallowed_brands_in(text):
            raise InvalidTelemetryConfigError(f"{label} brand leak: {text!r}")
        if emoji_in(text) or percent_encoded_emoji_in(text):
            raise InvalidTelemetryConfigError(f"{label} emoji: {text!r}")


@dataclass(frozen=True)

def __post_init__(self) -> None:
    if not self.brand.strip():
        raise InvalidTelemetryConfigError("brand must be non-empty")
    if disallowed_brands_in(self.brand):
        raise InvalidTelemetryConfigError(f"brand collides with a third-party brand: {self.brand!r}")
    if not self.shortcuts:
        raise InvalidTelemetryConfigError("shortcuts must be non-empty")
    if not self.tips:
        raise InvalidTelemetryConfigError("tips must be non-empty")
    if not self.phases:
        raise InvalidTelemetryConfigError("phases must be non-empty")
    keys = [phase.key for phase in self.phases]
    if len(keys) != len(set(keys)):
        raise InvalidTelemetryConfigError(f"duplicate phase key in {keys}")
    missing = _REQUIRED_PHASES - set(keys)
    if missing:
        raise InvalidTelemetryConfigError(f"missing required phase(s): {sorted(missing)}")
    _assert_clean("tagline", self.tagline)
    for shortcut in self.shortcuts:
        _assert_clean("shortcut", shortcut.keys, shortcut.description)
    for tip in self.tips:
        _assert_clean("tip", tip.title, tip.body)
    for phase in self.phases:
        _assert_clean("phase", phase.label)

