    if "/" in name or "\\" in name or "\x00" in name or ".." in name:
        raise ValueError(f"invalid recipe name: {name!r}")
    path = _recipe_table().get(name)
    if path is None:
        raise ValueError(f"unknown recipe name: {name!r}")
    # Defence in depth: the looked-up entry must still resolve inside the
    # dir (protects against a symlinked TOOL_RECIPES_DIR component).
    base = TOOL_RECIPES_DIR.resolve()
    resolved = path.resolve()
    if resolved.parent != base:
        raise ValueError(f"recipe path escapes recipes dir: {name!r}")
    return resolved

def load_recipe(name: str) -> InstallRecipe | None:
    """Load a tool recipe from ``tool_recipes/<name>.yaml`` (or ``None``).

    A malformed recipe is logged and treated as absent so one bad file can
    never break the whole registry. An invalid (traversal) name is likewise
    treated as absent so a hostile ``<name>`` URL segment can never cause a
    filesystem read outside ``TOOL_RECIPES_DIR``. Names outside the shipped
    recipe allowlist are treated as absent before any path is built
    (CodeQL #48/#49/#52): only directory-listed stems ever reach the
    filesystem.
    """
    if name not in set(list_recipes()):
        return None
    try:
        path = _recipe_path(name)
    except ValueError:
        log.warning("tool_install: rejected invalid recipe name %r", name)
        return None
    if not path.is_file():
        return None
    try:
        data = yaml.safe_load(path.read_text(encoding="utf-8")) or {}
    except Exception as exc:
        log.warning("tool_install: bad recipe %s: %s", path, exc)
        return None
    if not isinstance(data, dict):
        return None
    git = data.get("git") or {}
    if not isinstance(git, dict):
        git = {}
    recipe = InstallRecipe(
        name=str(data.get("name") or name),
        apt=str(data["apt"]) if data.get("apt") else None,
        repo_url=str(git["repo_url"]) if git.get("repo_url") else None,
        install_path=str(git["install_path"]) if git.get("install_path") else None,
        install_command=str(git["install_command"]) if git.get("install_command") else None,
        description=str(data

def recipe_available(name: str) -> bool:
    """True when a recipe exists for ``name`` (the UI gates the button on this)."""
    return load_recipe(name) is not None

def tool_available(binary: str) -> bool:
