def build_subdomain_tree(subdomains: list[str]) -> str:
    if not subdomains:
        return ""
    lines: list[str] = []
    base = ""
    for s in sorted(subdomains):
        parts = s.split(".")
        if len(parts) < 2:
            lines.append(f"  {s}")
            continue
        tld_domain = ".".join(parts[-2:])
        if base != tld_domain:
            if base:
                lines.append("")
            base = tld_domain
            lines.append(f"  {base}")

        sub_parts = parts[:-2]
        if sub_parts:
            prefix = "    " + " → ".join(reversed(sub_parts))
            lines.append(prefix)

    return "\n".join(lines)

def build_executive_summary(
    critical_findings: list[str],
    total_targets: int,
    domain: str,
    classification: str = "TLP:AMBER",
) -> str:
    lines = [
        "## Executive Summary",
        "",
        f"**Target:** {domain}",
        f"**Total targets analysed:** {total_targets}",
        f"**Classification:** {classification}",
        "",
    ]
    if critical_findings:
        lines.append("### Critical Findings")
        for f in critical_findings:
            lines.append(f"- **{f}**")
        lines.append("")

    return "\n".join(lines)

def _iocs(entities: Iterable[Dict[str, Any]]) -> List[str]:
    """The sections the next responder (CTI team, SOC) actually pastes
    into a ticket. Domains, IPs, emails, hashes, CVEs, crypto addresses."""
    bucket: Dict[str, List[str]] = {
        "domains": [], "ips": [], "emails": [],
        "hashes": [], "cves": [], "crypto": [],
    }
    for e in entities:
        t = e.get("type", "")
        v = e.get("value", "")
        if not v:
            continue
        if t == "domain":
            bucket["domains"].append(v)
        elif t in ("ipv4", "ipv6"):
            bucket["ips"].append(v)
        elif t == "email":
            bucket["emails"].append(v)
        elif t in ("md5", "sha1", "sha256"):
            bucket["hashes"].append(v)
        elif t == "cve":
            bucket["cves"].append(v)
        elif t in ("btc_address", "eth_address"):
            bucket["crypto"].append(v)
    out: List[str] = []
    out.append("## IOCs")
    out.append("")
    for label, key in (
        ("Domains", "domains"), ("IPs", "ips"),
        ("Emails", "emails"), ("Hashes", "hashes"),
        ("CVEs", "cves"), ("Crypto addresses", "crypto"),
    ):
        vals = sorted(set(bucket[key]))
        if not vals:
            continue
        out.append(f"### {label} ({len(vals)})")
        for v in vals[:50]:  # cap to keep the report readable
            out.append(f"- `{v}`")
        if len(vals) > 50:
            out.append(f"- … and {len(vals) - 50} more")

    def deco(backend_or_cls: Any) -> LLMBackend:
        backend: LLMBackend
        if isinstance(backend_or_cls, type):
            backend = backend_or_cls()
        else:
            backend = backend_or_cls
        if name in BACKENDS:
            log.debug("re-registering LLM backend %r", name)
        BACKENDS[name] = backend
        return backend
    return deco


