    """Symmetric diff between two cases by entity (type, value).

    Query string: ?a=<case_id>&b=<case_id>
    Returns the entities present in B but not in A ("added"), the
    inverse ("removed"), and the per-type breakdown. The UI uses
    this to show "what's new since last run" without a re-query.
    """
    a = (request.args.get("a") or "").strip()
    b = (request.args.get("b") or "").strip()
    if not a or not b:
        return jsonify({"error": "a and b query params are required"}), 400
    if a == b:
        return jsonify({"error": "a and b must be different cases"}), 400
    # Ensure both exist — surface 404 instead of an empty diff.
    if not case_store.get_case(a):
        return jsonify({"error": f"unknown case {a}"}), 404
    if not case_store.get_case(b):
        return jsonify({"error": f"unknown case {b}"}), 404
    return jsonify(case_store.diff_entities(a, b))

@app.route("/api/intel/resolve", methods=["GET"])
@_rate_limit_decorator(event="api_intel_resolve")
@require_auth
@_provides(intel_resolver, "intel resolver unavailable")

def api_intel_graph() -> Any:
    """Cypher query against the Kùzu persistent graph.

    Examples:
      GET /api/intel/graph?q=MATCH%20(n%3AEnt)%20RETURN%20n.id%20LIMIT%2010
    """
    q = request.args.get("q", "").strip()
    if not q:
        return jsonify({
            "error": "missing query parameter",
            "usage": "/api/intel/graph?q=<cypher>&limit=N",
        }), 400
    # Defence: only allow MATCH / RETURN-style read queries.
    # We don't want the public endpoint to run arbitrary writes
    # (CREATE / MERGE / DELETE / SET) without auth.
    upper = q.upper().lstrip()
    if not (upper.startswith("MATCH") or upper.startswith("RETURN") or upper.startswith("WITH")):
        return jsonify({
            "error": "read-only endpoint — queries must start with MATCH/RETURN/WITH",
        }), 400
    for forbidden in ("CREATE", "MERGE", "DELETE", "SET ", "DETACH", "DROP", "ALTER"):
        if forbidden in upper:
            return jsonify({
                "error": f"forbidden keyword {forbidden!r} — read-only endpoint",
            }), 400
    try:
        rows = kuzu_backend.cypher(q)
    except Exception:
        # Issue #44: log the Kuzu error server-side, return a
        # generic message. The old "detail" field carried table
        # names, column names, and query fragments back to the
        # client.
        log.exception("cypher query failed")
        return jsonify({"error": "cypher-failed"}), 400
    return json

def api_intel_stats() -> Any:
