def api_analyze_stream() -> Any:
    body = request.get_json(silent=True) or {}
    q = validate_query(str(body.get("query") or ""))
    model = (body.get("model") or "").strip() or None
    observations = body.get("observations")
    if not isinstance(observations, list):
        observations = []
    timeout = PIVOT.clamp_deadline(
        float(body.get("timeout_s", LLM_REQUEST_TIMEOUT))
    )

    q_in = queue.Queue(maxsize=64)

def _run() -> None:
    try:
        prompt = f"Produce an intelligence assessment of the target '{q.normalised}'."
        # graph_rag_search: contexto rankeado por la query para la
        # IA local. Fail-soft: si no hay grafo, el prompt va intacto.
        block = _graph_rag_block(f"assess {q.normalised}")
        if block:
            prompt += "\n\n" + block
        for chunk in orch.llm.stream(
            prompt,
            context=observations, model=model, request_timeout=timeout,
        ):
            q_in.put(chunk)
    except Exception:
        # CWE-209: log the detail server-side, stream a generic error.
        log.exception("analyze stream failed")
        q_in.put({"kind": "error", "text": "analysis failed; see server logs"})
    finally:
        q_in.put({"kind": "done"})

threading.Thread(target=_run, daemon=True, name="estorides-analyze").start()

        def gen():
            yield (
                "event: hello\n"
                f"data: {json.dumps({'query': q.normalised, 'model': model or 'auto'})}\n\n"
            )
            while True:
                try:
                    chunk = q_in.get(timeout=STREAM.poll_interval_seconds)
                except queue.Empty:
                    yield f": keepalive {int(time.time())}\n\n"
                    continue
                if chunk.get("kind") == "done":
                    yield "event: closed\ndata: {}\n\n"
                    return
                yield f"data: {json.dumps(chunk)}\n\n"

        return _sse_response(gen())

    return app


# The web server is sync (Flask). The discoverer needs an asyncio
# loop. We start a long-lived daemon thread that owns a loop and
# use `asyncio.run_coroutine_threadsafe` from the request handlers
# above to dispatch `start_discover` into it. This avoids spinning
# up a new loop per request and keeps the SSE writer in the same
# loop that the discoverer task runs in.

