function handleRunStreamEvent(d) {
  switch (d.type) {
    case 'target_start':
      setStatusDot('busy');
      setStatus('querying');
      break;
    case 'source_tick':
      setStatusDot('busy');
      if (d.source) {
        setStatus('querying ' + d.source);
      }
      break;
    case 'source_result':
      appendStreamObservation(d.observation);
      break;
    case 'entity':
      appendStreamEntity(d.entity, d.from);
      break;
    case 'target_done':
      if (d.analysis && d.analysis.content) {
        // Keep the analysis context in sync with the Results tab. We do NOT
        // overwrite _lastRun.query here — a discovered lead must never
        // replace the user's original query.
        loadAnalysisModels();
        renderAnalysis(d.analysis);
      }
      if (d.graph) renderGraphSummary(d.graph);
      break;
    case 'stopping':
      setStatus('stopping: ' + (d.reason || 'budget exhausted'));
      break;
    case 'fatal':
      setStatusDot('error');
      setStatus('error: ' + (d.error || 'pivot failed'));
      break;
  }
}

