function stopDiscover() {
  if (_discoverJobId) {
    fetch('/api/discover/stop', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ job_id: _discoverJobId }),
    }).catch(() => { /* swallow — best effort */ });
  }
  if (_discoverEventSource) {
