function djb2KindColor(name) {
  var h = 5381, i, sat, light, hue;
  name = String(name || 'unknown');
  for (i = 0; i < name.length; i++) {
    h = ((h << 5) + h + name.charCodeAt(i)) >>> 0;
  }
  hue = h % 360;
  sat = 55 + ((h >> 8) % 12);
  light = 58 + ((h >> 16) % 10);
  return 'hsl(' + hue + ', ' + sat + '%, ' + light + '%)';
}

