  fields.parser.value = s.parser || 'raw_text';
  fields.reqKey.checked = !!s.requires_key;
  fields.keyEnv.value = s.key_env || '';
  fields.keyEnv.disabled = !s.requires_key;
  fields.contact.value = s.contact || 'none';
